import ast, os, sys, json

def has_doc(p):
    src = open(p, encoding='utf-8').read()
    t = ast.parse(src)
    return bool(t.body and isinstance(t.body[0], ast.Expr) and isinstance(t.body[0].value, ast.Constant) and isinstance(t.body[0].value.value, str))

def insert(p, doc):
    lines = open(p, encoding='utf-8').read().split('\n')
    idx = 0
    # skip shebang / encoding lines
    if idx < len(lines) and lines[idx].startswith('#!'):
        idx += 1
    if idx < len(lines) and 'coding' in lines[idx] and lines[idx].startswith('#'):
        idx += 1
    # skip leading comment lines (but not blank lines separating them)
    while idx < len(lines) and lines[idx].startswith('#'):
        idx += 1
    block = ['"""' + doc + '"""', '']
    new = lines[:idx] + block + lines[idx:]
    open(p, 'w', encoding='utf-8').write('\n'.join(new))

if __name__ == '__main__':
    mapping = json.load(open(sys.argv[1]))
    changed = 0
    for p, doc in mapping.items():
        if not os.path.exists(p):
            print('MISSING', p); continue
        if has_doc(p):
            print('SKIP', p); continue
        insert(p, doc)
        changed += 1
    print('changed', changed)
PYEOF
echo ok"}}
