import ast, sys, json

def has_doc(src):
    t = ast.parse(src)
    return bool(t.body and isinstance(t.body[0], ast.Expr) and isinstance(t.body[0].value, ast.Constant) and isinstance(t.body[0].value.value, str))

def insert(path, doc):
    src = open(path, encoding='utf-8').read()
    if has_doc(src):
        return False
    lines = src.splitlines(keepends=True)
    idx = 0
    # skip shebang / encoding / leading comments and blank lines
    while idx < len(lines):
        s = lines[idx].strip()
        if s.startswith('#') or s == '':
            idx += 1
        else:
            break
    new = lines[:idx] + ['"""' + doc + '"""\n'] + lines[idx:]
    open(path, 'w', encoding='utf-8').write(''.join(new))
    return True

mapping = json.load(open(sys.argv[1]))
n = 0
for p, d in mapping.items():
    if insert(p, d):
        n += 1
print('changed', n)
PYEOF
